<?php
require_once dirname(__DIR__,2).'/app/bootstrap.php';$pdo=db();
if($_SERVER['REQUEST_METHOD']==='GET'){$admin=isset($_GET['admin']);if($admin)require_admin();$q=$pdo->query('SELECT * FROM news_posts'.($admin?'':" WHERE status='published'").' ORDER BY id DESC LIMIT 100');json_out(['posts'=>$q->fetchAll(),'csrf'=>$admin?csrf_token():null]);}
$u=require_admin();require_method('POST');require_csrf();$d=json_body();$id=(int)($d['id']??0);$title=trim((string)($d['title']??''));$rawBody=trim((string)($d['body']??''));require_once dirname(__DIR__,2).'/app/rich_text.php';$html=tdc_rich_text($rawBody);$body=trim(strip_tags($html));$category=text_cut(trim((string)($d['category']??'')),0,80);$cover=trim((string)($d['cover_url']??''));$status=(string)($d['status']??'draft');if(!$title||text_len($title)>200||!$body||text_len($body)>40000||!in_array($status,['draft','published'],true)||($cover&&!preg_match('#^(https://|/)[^\s<>"\']+$#',$cover)))json_out(['error'=>'Check title, body, cover image and status.'],422);
// Store text; the browser renders formatting without accepting arbitrary executable HTML.
if($id)$pdo->prepare('UPDATE news_posts SET title=?,category=?,body=?,cover_url=?,status=?,body_html=? WHERE id=?')->execute([$title,$category,$body,$cover,$status,$html,$id]);else{$pdo->prepare('INSERT INTO news_posts(title,category,body,cover_url,status,body_html) VALUES(?,?,?,?,?,?)')->execute([$title,$category,$body,$cover,$status,$html]);$id=(int)$pdo->lastInsertId();}audit('news.saved',(int)$u['id'],['id'=>$id,'status'=>$status]);json_out(['ok'=>true,'id'=>$id]);
